.listen-button {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;

font-family: var(--font-helveticaneue);
  padding: 0.8rem 1rem;
  background-color: #000;
  color: #fff;

  font-size: 1.1rem;
  text-decoration: none;


  transition:
    background-color 0.25s ease,
    color 0.25s ease,
    transform 0.25s ease;
}

.listen-button__arrow {
  color: var(--color-white);
  font-size: 1.6rem;
  line-height: 1;
  transition: transform 0.25s ease;
}

.listen-button:hover {
  background-color: #f42fa0;
  color:var(--color-white);
  transform: translateY(-3px);
}

.listen-button:hover .listen-button__arrow {
  color: var(--color-white);
  transform: translate(3px, -3px);
}



@media (max-width: 768px) {
  .news {
    min-height: auto;
    padding: 1rem;
    font-size: 1rem;
    overflow: hidden;
  }

  .news .big-titles {
    font-size: 8rem;
    line-height: 1;
    letter-spacing: -0.04em;
    margin-top: 0;
    margin-bottom: 1rem;
  }

  .news .section-cards {
    display: flex;
    gap: 1rem;
    overflow-x: auto;
    scroll-snap-type: x mandatory;
    -webkit-overflow-scrolling: touch;
  }

  .news .section-cards > * {
    flex: 0 0 60%;
    min-width: 0;
    scroll-snap-align: start;
  }

  .news .button {
    display: block;
    width: fit-content;
    margin: 1.5rem 0 0 auto;
  }
}

@media (max-width: 768px) {
  .events {
    min-height: auto;
    padding: 1.5rem 1rem 2rem;
    overflow: hidden;
  }

  .events .big-titles {
    font-size: 7.5rem;
    line-height: 0.9;
    letter-spacing: -0.04em;
    text-align: center;
    white-space: nowrap;
    margin: 0 0 2rem;
  }

  .events-cards {
    display: flex;
    gap: 0.75rem;
    overflow-x: auto;
    overflow-y: hidden;
    scroll-snap-type: x mandatory;
    -webkit-overflow-scrolling: touch;
    scrollbar-width: none;
  }

  .events-cards::-webkit-scrollbar {
    display: none;
  }

  .event-card {
    flex: 0 0 42%;
    min-width: 0;
    scroll-snap-align: start;
  }

  .event-card h3 {
    min-height: 3rem;
    font-size: 0.75rem;
    line-height: 1.4;
  }

  .event-card .event-date {
    font-size: 0.7rem;
    margin: 0.75rem 0 0.25rem;
  }

  .event-card img {
    width: 100%;
    aspect-ratio: 1.8 / 1;
    object-fit: cover;
  }

  .events > .button {
    margin: 1.5rem 0 0 auto;
    padding: 0.5rem 0.625rem;
    font-size: 0.625rem;
  }
}


