@media (max-width: 768px) {

  .site-header {
    padding: 0.5rem 1rem;
    max-height: 5rem;
    flex-wrap: wrap;
    background: white;
    box-sizing: border-box;
  }

  .header-right {
    margin-left: auto;
    position: relative;
    z-index: 1002;
  }

  .burger {
    display: flex;
    position: relative;
    z-index: 1003;
  }

  /* Menu fermé */
  .main-nav {
    display: none;
  }

  /* Menu ouvert : fond blanc plein écran */
  .main-nav.is-open {
    display: block;
    position: fixed;
    inset: 0;
    width: 100%;
    height: 100vh;
    height: 100dvh;
    padding: 9rem 1.25rem 2rem;
    box-sizing: border-box;
    background: white;
    z-index: 1001;
    overflow-y: auto;
      display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 2rem;

    position: fixed;
    inset: 0;
    width: 100%;
    height: 100vh;
    height: 100dvh;

    padding: 7rem 1.25rem 2rem;
    box-sizing: border-box;
    background: var(--color-white);
    z-index: 1001;
    overflow-y: auto;
  }

  .main-nav .subject {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 1.25rem;
  }

  .main-nav .lang {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.75rem;
  }



  /* Liens du menu */
  .main-nav .subject {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 1.25rem;
    width: 100%;
  }

  .main-nav a {
    font-size: 1.5rem;
    text-align: center;
  }
    .header-right .lang {
    display: none;
  }

  .main-nav.is-open .lang {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.75rem;
  }


  /* Animation du bouton burger en croix */
  .burger span {
    color: var(--color-blue);
    transition: transform 0.3s ease, opacity 0.3s ease;
  }

  .burger.is-open span:nth-child(1) {
    transform: translateY(0.45rem) rotate(45deg);
  }

  .burger.is-open span:nth-child(2) {
    opacity: 0;
  }

  .burger.is-open span:nth-child(3) {
    transform: translateY(-0.45rem) rotate(-45deg);
  }

}

/* VERSION MOBILE — PAGE ARTICLE */
@media (max-width: 768px) {

  /* ARTICLE PRINCIPAL */
  .article-page {
    position: relative;
    display: flex;
    flex-direction: column;
    min-height: auto;
    padding: 0;
    background-color: var(--color-pink);
    color: var(--color-black);
  }

  /* LIEN RETOUR */
  .back-link {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1rem;
    font-size: 0.75rem;
    color: var(--color-black);
  }

  /* IMAGE PRINCIPALE */
  .article-page > img {
    display: block;
    width: 100%;
    max-width: none;
    height: 9.25rem;
    object-fit: cover;
    object-position: center;
    margin: 0;
  }

  /* TITRE SUR L'IMAGE */
  .article-page h2 {
    position: relative;
    z-index: 1;
    font-family: var(--font-elzacondensed);
    font-size: clamp(2.5rem, 11vw, 3.5rem);
    line-height: 0.9;
    text-align: left;
    letter-spacing: normal;
    margin: -3.5rem 0 1rem;
    padding: 0 1rem;
    overflow-wrap: anywhere;
  }

  /* TEXTE DE L'ARTICLE */
  .article-page p {
    font-family: var(--font-helveticaneue);
    font-size: 0.875rem;
    line-height: 1.5;
    text-align: left;
    letter-spacing: normal;
    margin: 0;
    padding: 1rem 1.25rem 2rem;
  }

  /* À PROPOS DE SUPREMNOVA */
  .about-supremnova {
    position: relative;
    min-height: auto;
    max-height: none;
    padding: 0 1rem 2rem;
    overflow: hidden;
    background-color: var(--color-white);
    color: var(--color-pink);
  }

  /* IMAGE DERRIÈRE LE TITRE */
  .about-supremnova img {
    position: absolute;
    top: 0;
    left: 0;
    display: block;
    width: 100%;
    max-width: none;
    height: 8rem;
    object-fit: cover;
    object-position: center;
    margin: 0;
    z-index: 0;
  }

  .about-supremnova h2 {
    position: relative;
    z-index: 1;
    display: flex;
    flex-direction: column;
    justify-content: center;
    min-height: 8rem;
    font-family: var(--font-elzacondensed);
    font-size: clamp(2rem, 9vw, 2.75rem);
    line-height: 1.1;
    text-align: left;
    letter-spacing: normal;
    margin: 0 -1rem 1rem;
    padding: 0 1rem;
  }

  /* BIOGRAPHIE */
  .about-supremnova p {
    position: relative;
    z-index: 1;
    font-family: var(--font-helveticaneue);
    font-size: 0.875rem;
    line-height: 1.5;
    text-align: left;
    letter-spacing: normal;
    margin: 0;
    padding: 0 0 1rem;
  }

  /* BOUTON ÉCOUTER */
  .about-supremnova button {
    position: relative;
    z-index: 1;
    display: inline-block;
    width: auto;
    margin: 0;
    padding: 0.4rem 0.75rem;
    font-size: 0.7rem;
  }

}

